using System;using System.IO;using System.Linq;using System.Text;using System.Diagnostics;using System.Collections.Generic;
internal sealed class MigrationRecord {
 public int SchemaVersion{get;set;}public int SourceFormat{get;set;}public int TargetFormat{get;set;}public string Id{get;set;}public string SourceRoot{get;set;}public string TargetRoot{get;set;}public string ProgramRoot{get;set;}public string ReleaseSha256{get;set;}public string SourceFingerprint{get;set;}public string TargetFingerprint{get;set;}public string BackupFingerprint{get;set;}public string Backup{get;set;}public string Staged{get;set;}public string StoreId{get;set;}public string Status{get;set;}public string PreparedAt{get;set;}public string CommittedAt{get;set;}public string ExpectedConfigHash{get;set;}public List<ReleaseFile> Dependencies{get;set;}public bool Committed{get;set;}public string SourceAssetsFingerprint{get;set;}public string BackupAssets{get;set;}public string SourceVersion{get;set;}public List<string> Steps{get;set;}
}
internal sealed class SourceReadLease:IDisposable {
 readonly List<FileStream> streams=new List<FileStream>();internal SourceReadLease(string folder,Action check){try{foreach(string p in DataMigration.Files(folder,check)){check();streams.Add(new FileStream(p,FileMode.Open,FileAccess.Read,FileShare.Read));}}catch{Dispose();throw;}}public void Dispose(){foreach(var f in streams)f.Dispose();streams.Clear();}
}
internal static class DataMigration {
 internal const int FileLimit=4096,StateBudget=67108864;
#if TEST_BUILD
 internal static Action<string> Inject;
#endif
 static void Point(string phase){DataLocation.Phase=phase;
#if TEST_BUILD
 if(Inject!=null)Inject(phase);
#endif
 }
 internal static string[] Files(string folder,Action check){LocalImport.NoLinks(folder);var result=new List<string>();long bytes=0;var dirs=new Stack<string>();dirs.Push(folder);while(dirs.Count>0){check();string dir=dirs.Pop();LocalImport.NoLinks(dir);foreach(string d in Directory.GetDirectories(dir)){LocalImport.NoLinks(d);dirs.Push(d);if(dirs.Count>FileLimit)throw new InvalidDataException("目录数超过预算");}foreach(string f in Directory.GetFiles(dir)){check();LocalImport.NoLinks(f);bytes+=new FileInfo(f).Length;if(bytes>StateBudget||result.Count>=FileLimit)throw new InvalidDataException("状态快照超过64MiB/4096文件预算");result.Add(f);}}return result.OrderBy(x=>x,StringComparer.OrdinalIgnoreCase).ToArray();}
 internal static string Fingerprint(string folder,Action check){var b=new StringBuilder();foreach(string p in Files(folder,check)){check();if(Path.GetFileName(p)==".writer.lock")continue;b.Append(p.Substring(folder.TrimEnd('\\').Length+1).ToLowerInvariant()).Append('|').Append(new FileInfo(p).Length).Append('|').Append(Common.Hash(p)).Append('\n');}return PackageAnalysis.Digest(Encoding.UTF8.GetBytes(b.ToString()));}
 static void CopyTree(string source,string target,Action check){foreach(string p in Files(source,check)){check();string rel=p.Substring(source.TrimEnd('\\').Length+1);if(!FaultSafety.SafeRelative(rel))throw new InvalidDataException("快照相对路径不安全");string dst=Path.Combine(target,rel);if(dst.Length>245)throw new PathTooLongException("迁移目标路径超过245字符预算，请由Agent选择更短的固定数据位置；未提交");Directory.CreateDirectory(Path.GetDirectoryName(dst));CopyFile(p,dst,check);}}
 static void CopyFile(string source,string target,Action check){using(var src=new FileStream(source,FileMode.Open,FileAccess.Read,FileShare.Read))using(var dst=new FileStream(target,FileMode.CreateNew,FileAccess.Write,FileShare.None)){byte[] b=new byte[262144];int n;while((n=src.Read(b,0,b.Length))>0){check();dst.Write(b,0,n);}dst.Flush(true);}check();if(Common.Hash(source)!=Common.Hash(target))throw new IOException("复制复核失败，未提交");}
 static List<ReleaseFile> Dependencies(LibraryDocument doc,Action check){var rows=new List<ReleaseFile>();foreach(var x in doc.Items){check();if(!PackageAnalysis.HashText(x.RegisteredSha256))throw new InvalidDataException("资源完整哈希缺失，未迁移");string p=DataLocation.SafePath(x.SourcePath);LocalImport.NoLinks(p);if(!File.Exists(p)||new FileInfo(p).Length>536870912)throw new InvalidDataException("资源缺失或超出本轮单文件512MiB验证预算");string hash=V3Package.HashFile(p,check);if(hash!=x.RegisteredSha256)throw new InvalidDataException("资源与正式登记完整哈希不符，未迁移");rows.Add(new ReleaseFile{Path=p,Bytes=new FileInfo(p).Length,Sha256=hash});if(!String.IsNullOrEmpty(x.CoverPath)){string cover=DataLocation.SafePath(x.CoverPath);LocalImport.NoLinks(cover);if(new FileInfo(cover).Length>20971520)throw new InvalidDataException("持久封面超过20MiB预算");rows.Add(new ReleaseFile{Path=cover,Bytes=new FileInfo(cover).Length,Sha256=Common.Hash(cover)});}}return rows;}
 static void VerifyDependencies(List<ReleaseFile> rows,Action check){foreach(var r in rows){check();LocalImport.NoLinks(r.Path);if(new FileInfo(r.Path).Length!=r.Bytes||V3Package.HashFile(r.Path,check)!=r.Sha256)throw new IOException("准备后资源或封面变化，未切换");}}
 static void CheckSource(string root){DataLocation.SafePath(root);LocalImport.NoLinks(root);var doc=DataLocation.ReadSmall<LibraryDocument>(Path.Combine(root,"data","catalog.json"));if(doc==null||doc.Version!=1||doc.Items==null)throw new InvalidDataException("来源库格式不支持或损坏");var settings=DataLocation.ReadSmall<AppSettings>(Path.Combine(root,"data","settings.json"),16384);if(settings==null||settings.Version!=1||settings.Volume<0||settings.Volume>100)throw new InvalidDataException("来源设置损坏");}
 static Action Budget(Action cancel,Stopwatch clock){return ()=>{cancel();if(clock.Elapsed.TotalSeconds>120)throw new TimeoutException("迁移超过120秒预算，未继续提交");};}
 internal static MigrationRecord Prepare(string source,string target,string program,Action cancel){using(var gate=new UpgradeGate()){var clock=Stopwatch.StartNew();Action check=Budget(cancel,clock);source=DataLocation.SafePath(source);target=DataLocation.SafePath(target);program=DataLocation.SafePath(program);DataLocation.DataPath(target,program);if(DataLocation.Same(source,target)||LocalImport.Under(target,source)||LocalImport.Under(source,target))throw new InvalidDataException("迁移目标与来源重叠");VersionStore.CheckLegacyTools(Path.GetDirectoryName(program));if(File.Exists(DataLocation.ConfigPath)){var current=DataLocation.Load();DataLocation.ValidateStore(current,false);if(DataLocation.Same(current.DataRoot,target)&&DataLocation.Same(current.ActiveRoot,program)&&!String.IsNullOrEmpty(current.MigrationRecord)){var prior=DataLocation.ReadSmall<MigrationRecord>(current.MigrationRecord);if(DataLocation.Same(prior.SourceRoot,source)&&prior.StoreId==current.StoreId)return prior;}throw new InvalidOperationException("已有正式数据关联；不得再次从旧库迁移覆盖，请使用版本切换");}if(Directory.Exists(target)||File.Exists(target))throw new IOException("目标已存在，未覆盖或猜选库");Point("检查来源");CheckSource(source);using(var sourceLock=new SourceReadLease(Path.Combine(source,"data"),check)){string fingerprint=Fingerprint(Path.Combine(source,"data"),check);string hash=Common.Hash(VersionStore.ReleasePath(program));VersionStore.VerifyRelease(program,hash,1);string folder=Path.Combine(DataLocation.ControlRoot,"m");Directory.CreateDirectory(folder);string id="migration-"+DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,8),op=Path.Combine(folder,Guid.NewGuid().ToString("N").Substring(0,12));Directory.CreateDirectory(op);var r=new MigrationRecord{SchemaVersion=1,SourceFormat=1,TargetFormat=1,Id=id,SourceRoot=source,SourceVersion=Path.GetFileName(source),TargetRoot=target,ProgramRoot=program,ReleaseSha256=hash,SourceFingerprint=fingerprint,StoreId=Guid.NewGuid().ToString("N"),Backup=Path.Combine(op,"b"),Staged=Path.Combine(op,"s"),Status="检查中",PreparedAt=DateTimeOffset.Now.ToString("o"),ExpectedConfigHash=VersionStore.ConfigHash(),Steps=new List<string>()};string record=Path.Combine(op,"migration.json");DataLocation.InProgress=r;Common.SaveNew(record,r);
 try{r.Dependencies=Dependencies(DataLocation.ReadSmall<LibraryDocument>(Path.Combine(source,"data","catalog.json")),check);Point("复制备份");CopyTree(Path.Combine(source,"data"),r.Backup,check);r.BackupFingerprint=Fingerprint(r.Backup,check);if(r.BackupFingerprint!=fingerprint)throw new IOException("备份不是同一来源快照");r.Steps.Add("原数据按文件完整哈希备份；未删除来源");string assets=Path.Combine(source,"assets");if(Directory.Exists(assets)){r.SourceAssetsFingerprint=Fingerprint(assets,check);r.BackupAssets=Path.Combine(op,"a");CopyTree(assets,r.BackupAssets,check);if(Fingerprint(r.BackupAssets,check)!=r.SourceAssetsFingerprint)throw new IOException("持久封面资源备份不一致");CopyTree(r.BackupAssets,Path.Combine(r.Staged,"assets"),check);}
 Point("复制目标");CopyTree(r.Backup,Path.Combine(r.Staged,"data"),check);var doc=DataLocation.ReadSmall<LibraryDocument>(Path.Combine(r.Staged,"data","catalog.json"));foreach(var x in doc.Items){check();if(String.IsNullOrEmpty(x.CoverPath))continue;string old=x.CoverPath,ext=Path.GetExtension(old).ToLowerInvariant();if(!new[]{".jpg",".jpeg",".png",".bmp"}.Contains(ext))throw new InvalidDataException("持久封面扩展名不支持");string imageHash=Common.Hash(old),relative=Path.Combine("data","persistent-covers",imageHash+ext),copy=Path.Combine(r.Staged,relative);if(!File.Exists(copy)){Directory.CreateDirectory(Path.GetDirectoryName(copy));CopyFile(old,copy,check);}x.CoverPath=Path.Combine(target,relative);}
 Common.ReplaceJson(Path.Combine(r.Staged,"data","catalog.json"),doc);Common.SaveNew(Path.Combine(r.Staged,"store.json"),new StoreMarker{SchemaVersion=1,DataFormat=1,StoreId=r.StoreId});r.Steps.Add("封面复制到固定数据根；仅修改当前卡片CoverPath；CWP原路径与历史证据未改");Point("验证来源稳定");if(Fingerprint(Path.Combine(source,"data"),check)!=fingerprint)throw new IOException("复制期间源数据变化，未发布混合快照");if(r.SourceAssetsFingerprint!=null&&Fingerprint(Path.Combine(source,"assets"),check)!=r.SourceAssetsFingerprint)throw new IOException("源持久封面变化");VerifyDependencies(r.Dependencies,check);r.TargetFingerprint=Fingerprint(r.Staged,check);r.Status="prepared-not-committed";r.Steps.Add("备份、目标及源稳定性核验完成；尚未切换");Common.ReplaceJson(record,r);return r;
 }catch(Exception ex){r.Status="failed-not-committed";r.Steps.Add(ex.GetType().Name+"："+FaultSafety.Text(ex.Message));Common.ReplaceJson(record,r);if(Directory.Exists(r.Staged)){LocalImport.NoLinks(r.Staged);Directory.Delete(r.Staged,true);}throw;}}}}
 internal static Deployment Commit(string path,Action cancel){using(var gate=new UpgradeGate()){var clock=Stopwatch.StartNew();Action check=Budget(cancel,clock);path=DataLocation.SafePath(path);if(!LocalImport.Under(path,Path.Combine(DataLocation.ControlRoot,"m"))||Path.GetFileName(path)!="migration.json")throw new InvalidDataException("迁移记录不属于本软件");var r=DataLocation.ReadSmall<MigrationRecord>(path);DataLocation.InProgress=r;if(r==null||r.SchemaVersion!=1||r.SourceFormat!=1||r.TargetFormat!=1)throw new InvalidDataException("迁移记录格式不支持");string op=Path.GetDirectoryName(path);if(r.Backup!=Path.Combine(op,"b")||r.Staged!=Path.Combine(op,"s"))throw new InvalidDataException("迁移工作目录不符");if(File.Exists(DataLocation.ConfigPath)){var current=DataLocation.Load();if(current.StoreId==r.StoreId&&DataLocation.Same(current.DataRoot,r.TargetRoot)){DataLocation.ValidateStore(current,false);return current;}throw new InvalidDataException("已有其他数据关联，不覆盖或猜选");}if(r.Status!="prepared-not-committed"&&r.Status!="data-published-not-activated")throw new InvalidDataException("迁移尚未准备完成，禁止切换");VersionStore.CheckLegacyTools(Path.GetDirectoryName(r.ProgramRoot));Point("提交前复核");CheckSource(r.SourceRoot);using(var sourceLock=new SourceReadLease(Path.Combine(r.SourceRoot,"data"),check)){if(Fingerprint(Path.Combine(r.SourceRoot,"data"),check)!=r.SourceFingerprint)throw new IOException("准备后来源数据变化，必须重新准备；原库保持");if(Fingerprint(r.Backup,check)!=r.BackupFingerprint)throw new IOException("备份变化，未提交");if(r.SourceAssetsFingerprint!=null&&(r.BackupAssets!=Path.Combine(op,"a")||Fingerprint(Path.Combine(r.SourceRoot,"assets"),check)!=r.SourceAssetsFingerprint||Fingerprint(r.BackupAssets,check)!=r.SourceAssetsFingerprint))throw new IOException("持久封面来源或备份变化");VerifyDependencies(r.Dependencies,check);VersionStore.VerifyRelease(r.ProgramRoot,r.ReleaseSha256,1);DataLocation.DataPath(r.TargetRoot,r.ProgramRoot);string staged=r.Status=="data-published-not-activated"?r.TargetRoot:r.Staged;if(Fingerprint(staged,check)!=r.TargetFingerprint)throw new IOException("目标快照变化，未覆盖");if(r.Status=="prepared-not-committed"&&(Directory.Exists(r.TargetRoot)||File.Exists(r.TargetRoot)))throw new IOException("目标已存在，不覆盖");check();Point("发布数据目录");if(Fingerprint(Path.Combine(r.SourceRoot,"data"),check)!=r.SourceFingerprint)throw new IOException("提交前来源变化");if(r.Status=="prepared-not-committed"){Directory.Move(r.Staged,r.TargetRoot);r.Status="data-published-not-activated";Common.ReplaceJson(path,r);}var next=new Deployment{SchemaVersion=1,DataFormat=1,StoreId=r.StoreId,DataRoot=r.TargetRoot,ActiveRoot=r.ProgramRoot,ReleaseSha256=r.ReleaseSha256,MigrationRecord=path,CommittedAt=DateTimeOffset.Now.ToString("o")};using(var lease=new DataLease(r.TargetRoot)){DataLocation.ValidateStore(next,true);Point("提交程序数据关联");if(Fingerprint(Path.Combine(r.SourceRoot,"data"),check)!=r.SourceFingerprint)throw new IOException("提交前来源变化");VersionStore.Publish(next,r.ExpectedConfigHash);}r.Committed=true;r.Status="committed";r.CommittedAt=next.CommittedAt;r.Steps.Add("固定数据根与新程序关联已原子提交；旧库未改；无播放确认新增");Common.ReplaceJson(path,r);return next;}}}
 // Add-only completion for a transaction prepared by the preceding build. Never overwrites a user file.
 internal static object CompleteAssets(string path,Action cancel){using(var gate=new UpgradeGate()){path=DataLocation.SafePath(path);if(!LocalImport.Under(path,Path.Combine(DataLocation.ControlRoot,"m"))||Path.GetFileName(path)!="migration.json")throw new InvalidDataException("迁移记录不属于本软件");var r=DataLocation.ReadSmall<MigrationRecord>(path);var current=DataLocation.Load();if(r.StoreId!=current.StoreId||!DataLocation.Same(r.TargetRoot,current.DataRoot))throw new InvalidDataException("补充资源不属于当前库");using(var lease=new DataLease(current.DataRoot)){var clock=Stopwatch.StartNew();Action check=Budget(cancel,clock);string source=Path.Combine(r.SourceRoot,"assets"),target=Path.Combine(current.DataRoot,"assets"),receipt=Path.Combine(Path.GetDirectoryName(path),"assets-completed.json");string hash=Fingerprint(source,check);if(Directory.Exists(target)){if(Fingerprint(target,check)!=hash)throw new IOException("目标持久图片已存在且不同，未覆盖");return new{alreadyComplete=true,source=source,target=target,fingerprint=hash};}string temp=Path.Combine(current.DataRoot,".assets-"+Guid.NewGuid().ToString("N").Substring(0,8));try{CopyTree(source,temp,check);if(Fingerprint(temp,check)!=hash||Fingerprint(source,check)!=hash)throw new IOException("补充资源复制期间变化");check();Directory.Move(temp,target);var proof=new{schemaVersion=1,operation="add-only-persistent-assets",source=source,target=target,fingerprint=hash,createdAt=DateTimeOffset.Now.ToString("o"),existingDataOverwritten=false,originalEvidenceRewritten=false};Common.SaveNew(receipt,proof);return proof;}finally{if(Directory.Exists(temp)){LocalImport.NoLinks(temp);Directory.Delete(temp,true);}}}}}

}
